INSERT INTO metric_sub_category(category_id,sub_category_code,sub_category_name,status) SELECT id,'eff_e80b3f696306','运行效率-接口效率-账单查询','enabled' FROM metric_category WHERE category_code='system_run' AND NOT EXISTS(SELECT 1 FROM metric_sub_category sc WHERE sc.category_id=metric_category.id AND sc.sub_category_name='运行效率-接口效率-账单查询') ON DUPLICATE KEY UPDATE sub_category_name=VALUES(sub_category_name);
INSERT INTO metric_item(category_id,sub_category_code,sub_category_name,metric_code,metric_name,metric_type,metric_definition,unit,data_source,collect_frequency,status) SELECT c.id,sc.sub_category_code,'运行效率-接口效率-账单查询','EFF_20261117_024','app账单查询成功率','导入','app账单查询成功率','%','running_efficiency','10分钟',1 FROM metric_category c JOIN metric_sub_category sc ON sc.category_id=c.id AND sc.sub_category_name='运行效率-接口效率-账单查询' WHERE c.category_code='system_run' ON DUPLICATE KEY UPDATE metric_definition=VALUES(metric_definition),unit=VALUES(unit),collect_frequency=VALUES(collect_frequency);
INSERT INTO metric_monitor_config(metric_id,alarm_threshold,alarm_condition,alarm_status,gongdan_threshold,gongdan_status) SELECT id,99,'<',1,NULL,0 FROM (SELECT m.id FROM metric_item m JOIN metric_category c ON c.id=m.category_id WHERE c.category_code='system_run' AND m.metric_code='EFF_20261117_024') selected ON DUPLICATE KEY UPDATE alarm_threshold=VALUES(alarm_threshold),alarm_condition=VALUES(alarm_condition),alarm_status=1;
INSERT INTO alarm_strategy(strategy_name,strategy_type,target_type,target_id,target_name,alarm_enabled,alarm_threshold,alarm_condition,gongdan_enabled,status) SELECT CONCAT('指标阈值-',m.metric_name),'metric','metric',m.id,m.metric_name,1,99,'<',0,1 FROM metric_item m WHERE m.id IN (SELECT m.id FROM metric_item m JOIN metric_category c ON c.id=m.category_id WHERE c.category_code='system_run' AND m.metric_code='EFF_20261117_024') AND NOT EXISTS(SELECT 1 FROM alarm_strategy s WHERE s.target_type='metric' AND s.strategy_type='metric' AND s.target_id=m.id);
